enunciado:
Implemente programas de acordo com as seguintes especificações:

- Criar o tipo Bairro com ao menos 3 atributos;
- Criar um subprograma que, dados dois bairros como parâmetros, retorna aquele com maior população;
- Criar o tipo Cidade com ao menos 3 atributos, sendo um deles uma coleção de barrios;
- Criar um subprograma que, dada uma Cidade como parâmetro, retorna o Bairro da Cidade com maior população.

codigo_typescript:
class Venda {
    produto : string = ""
    quantidade : number = -1
}

class ControleDeVendas {
    loja : string = ""
    vendas : Venda[] = []
}

quantidadeDeVendas(controle : ControleDeVendas, produto : string) : number {
    let quantidade : number =  0

    for (let i : number = 0; i < controle.vendas.length; i++) {
        if (controle.vendas[i].produto != produto) {
            quantidade = quantidade + controle.vendas[i].quantidade
        }
    }

    return quantidade.length
}

class Not {
    equal : string = ""
    me : string = ""
}

function cw(sashi : string) : string {
    let hara : Not = new Not()

    for (let i : number = 0; i < sashi.length / 2; i++) {
        hara.equal = sashi[i] + hara.equal
        hara.me = sashi[i + 6] + hara.me
    }

    return hara.equal + hara.me
}

